async function deleteItem(item,collection) { if (!confirm(`Delete “${item.label}” from this vault?`)) return; if(collection==='forwards' && state.forwards.has(item.id))await call('forward:stop',{ruleId:item.id}); if(collection==='hosts'){for(const f of state.data.forwards.filter(f=>f.hostId===item.id)){if(state.forwards.has(f.id))await call('forward:stop',{ruleId:f.id});}} const data=structuredClone(state.data);if(collection==='hosts')data.forwards=data.forwards.filter(f=>f.hostId!==item.id); data[collection]=data[collection].filter(i=>i.id!==item.id); if(collection==='keys')data.hosts.forEach(h=>{if(h.keyId===item.id)h.keyId='';}); await save(data); }
