 if(collection==='keys'){fields.append(field('privateKey','Private key (PEM / OpenSSH)',item?.privateKey,'textarea',true));fields.append(button('Import key from file…','wide',async()=>{const result=await call('key:read');if(result?.privateKey)fields.querySelector('[name=privateKey]').value=result.privateKey;}),field('passphrase','Key passphrase (optional)',item?.passphrase,'password'));}
