 $('editor-form').onsubmit=action(async event=>{event.preventDefault();const values=Object.fromEntries(new FormData(event.currentTarget));if(collection==='hosts')values.port=Number(values.port);if(collection==='forwards'){values.bindPort=Number(values.bindPort);if(values.type==='dynamic'){delete values.targetAddress;delete values.targetPort;}else values.targetPort=Number(values.targetPort);if(item&&state.forwards.has(item.id))await call('forward:stop',{ruleId:item.id});}const data=structuredClone(state.data);const record={...item,...values,id:item?.id||crypto.randomUUID()};if(collection==='hosts'){record.terminalTheme=fields.terminalTheme();record.jumpHostIds=fields.jumpHostIds();delete record.jumpHostId;record.migrationBlockers=record.migrationBlockers?.filter(text=>!/jump-host/i.test(text));record.requiresMigrationSetup=!!record.migrationBlockers?.length||!record.username?.trim();}if(collection==='forwards'&&record.type==='dynamic'){delete record.targetAddress;delete record.targetPort;}const index=data[collection].findIndex(i=>i.id===record.id);if(index<0)data[collection].push(record);else data[collection][index]=record;await save(data);$('editor').close();fields.replaceChildren();});$('editor').showModal();
