document.addEventListener('pointermove',event=>{
 const drag=pointerTerminalDrag;if(!drag||state.locked)return;
 if(!drag.started){if(Math.hypot(event.clientX-drag.x,event.clientY-drag.y)<6)return;drag.started=true;state.dragSession=drag.id;document.body.classList.add('terminal-dragging');}
 event.preventDefault();const hit=document.elementFromPoint(event.clientX,event.clientY),pane=hit?.closest('.terminal-pane.active,.empty-terminal');
 document.querySelectorAll('[data-drop-zone]').forEach(p=>{if(p!==pane)delete p.dataset.dropZone;});
 hoverDragTab(pane?null:hit?.closest('[data-workspace],[data-session]'));
 if(pane)pane.dataset.dropZone=dropZone(event,pane);
},{passive:false});
document.addEventListener('pointerup',event=>{
 const drag=pointerTerminalDrag;if(!drag?.started){clearTerminalDrag();return;}
 event.preventDefault();suppressDragClickUntil=performance.now()+250;
 const pane=document.elementFromPoint(event.clientX,event.clientY)?.closest('.terminal-pane.active,.empty-terminal');
 const index=pane?Number(pane.dataset.slot):-1,zone=pane?dropZone(event,pane):null;
 clearTerminalDrag();if(!state.locked&&state.sessions.has(drag.id)&&index>=0&&zone)dockSession(drag.id,index,zone);
 if(!state.locked)renderAllTabs();
});
document.addEventListener('pointercancel',()=>{const dragging=pointerTerminalDrag?.started;clearTerminalDrag();if(dragging){suppressDragClickUntil=performance.now()+250;if(!state.locked)renderAllTabs();}});

function renderAllTabs(){
 if(pointerTerminalDrag?.started)return; // Keep the grabbed tab mounted until release.
 const tabs=$('terminal-tabs');tabs.replaceChildren();
 const grouped=new Set();
 for(const [key,g] of state.workspaces){g.slots.forEach(id=>grouped.add(id));const tab=button(`▦ Workspace · ${g.slots.length}`,!state.activePicker&&state.activeWorkspace===key?'active':'',()=>showWorkspace(key));tab.dataset.workspace=key;terminalMenu(tab,()=>g.active||g.slots.find(id=>state.sessions.has(id)));tab.title=g.slots.map(id=>state.sessions.get(id)?.host.label).join(' · ');const close=el('span',null,'×');close.title='Close workspace';close.addEventListener('click',action(async e=>{e.stopPropagation();for(const id of [...g.slots])await closeSession(id);}));tab.append(close);tabs.append(tab);

 }
 for(const s of state.sessions.values()){
  if(grouped.has(s.id))continue;
  const tab=button(`${s.closed?'○':'●'} ${s.host.label}`,!state.activePicker&&s.id===state.active?'active':'',()=>showSession(s.id));tab.dataset.session=s.id;terminalMenu(tab,()=>s.id);makeTerminalDraggable(tab,s.id);
  const close=el('span',null,'×');close.title='Close session';close.addEventListener('click',action(async e=>{e.stopPropagation();const picker=state.activePicker;await closeSession(s.id);if(picker&&state.pickerTabs.has(picker))showHostPicker(picker);}));tab.append(close);tabs.append(tab);
 }
 for(const [id] of state.pickerTabs){const tab=button('New Tab',state.activePicker===id?'active':'',()=>showHostPicker(id));tab.dataset.picker=id;const close=el('span',null,'×');close.title='Close new tab';close.addEventListener('click',e=>{e.stopPropagation();closeHostPicker(id);});tab.append(close);tabs.append(tab);}
 const add=button('＋','new-terminal-tab',openHostTab);add.id='new-terminal-tab';add.title=`New tab (${shortcutLabel}T)`;add.setAttribute('aria-label','New terminal tab');tabs.append(add);
}
function openHostTab(){hideTerminalMenu();if(state.locked||document.querySelector('dialog[open]'))return;const id=crypto.randomUUID();state.pickerTabs.set(id,{query:'',connecting:false});showHostPicker(id);}
function showHostPicker(id){if(state.locked||!state.pickerTabs.has(id))return;clearTerminalDrag();state.activePicker=id;terminalMode();$('terminal-tools').hidden=true;$('terminal-panes').hidden=true;$('host-picker').hidden=false;$('host-picker-search').value=state.pickerTabs.get(id).query;renderAllTabs();renderHostChoices();$('host-picker-search').focus();}
function closeHostPicker(id){const active=state.activePicker===id;state.pickerTabs.delete(id);if(!active){renderAllTabs();return;}state.activePicker=null;const other=[...state.pickerTabs.keys()].at(-1);if(other)showHostPicker(other);else if(state.sessions.size)showSession(state.active&&state.sessions.has(state.active)?state.active:state.sessions.keys().next().value);else render();}
function pickerHosts(){const query=$('host-picker-search').value.trim().toLowerCase();return state.data.hosts.filter(h=>[h.label,h.address,h.username,h.group].filter(Boolean).join(' ').toLowerCase().includes(query));}
function renderHostChoices(){if(state.locked||!state.activePicker)return;const hosts=pickerHosts(),container=$('host-picker-results');container.replaceChildren();$('host-picker-count').textContent=`${hosts.length} ${hosts.length===1?'host':'hosts'}`;for(const host of hosts){const row=button('','picker-host',()=>choosePickerHost(host));row.append(el('span','picker-host-icon','›_'));const name=el('span','picker-host-name');name.append(el('strong',null,host.label),el('small',null,`${host.username}@${host.address}:${host.port||22}`));row.append(name,el('span','picker-host-group',host.group||'Personal'));container.append(row);}if(!hosts.length)container.append(el('p','picker-empty',state.data.hosts.length?'No matching hosts. Try a different search.':'No hosts saved yet. Add a host in Workspace.'));}
async function choosePickerHost(host){const id=state.activePicker,picker=state.pickerTabs.get(id);if(!picker||picker.connecting)return;picker.connecting=true;try{await connect(host,id);}finally{if(state.pickerTabs.has(id))picker.connecting=false;}}
$('host-picker-search').addEventListener('input',()=>{const picker=state.pickerTabs.get(state.activePicker);if(picker)picker.query=$('host-picker-search').value;renderHostChoices();});
$('host-picker-search').addEventListener('keydown',action(async event=>{if(event.key==='Enter'){event.preventDefault();const host=pickerHosts()[0];if(host)await choosePickerHost(host);}else if(event.key==='ArrowDown'){event.preventDefault();$('host-picker-results').querySelector('button')?.focus();}else if(event.key==='Escape'){event.preventDefault();closeHostPicker(state.activePicker);}}));
document.addEventListener('keydown',event=>{if(!(usesControlShortcuts?(event.ctrlKey&&!event.metaKey):(event.metaKey&&!event.ctrlKey))||event.altKey||event.shiftKey||state.locked||document.querySelector('dialog[open]'))return;if(event.key.toLowerCase()==='r'){event.preventDefault();event.stopImmediatePropagation();if(!event.repeat)returnToSession();}else if(event.key.toLowerCase()==='t'){event.preventDefault();event.stopImmediatePropagation();if(!event.repeat)openHostTab();}else if(event.key.toLowerCase()==='k'&&state.activePicker){event.preventDefault();$('host-picker-search').focus();}},true);

$('host-picker').querySelector('.picker-search>span').textContent=shortcutLabel+'K';

$('import-vault').addEventListener('click',()=>{$('settings').close();$('import-password').value='';$('import-dialog').showModal();$('import-password').focus();});
for(const id of ['close-import','cancel-import'])$(id).addEventListener('click',()=>{$('import-dialog').close();$('import-password').value='';});
$('import-dialog').addEventListener('close',()=>{$('import-password').value='';});
$('import-form').addEventListener('submit',action(async e=>{e.preventDefault();const result=await call('vault:import',{password:$('import-password').value});if(result?.canceled)return;$('import-dialog').close();applyVault(result);const s=result.importSummary;notify(`Imported ${s.hostsAdded} hosts; merged ${s.hostsMerged}; added ${s.keysAdded} keys.${s.hostsNeedingSetup?' '+s.hostsNeedingSetup+' hosts need configuration (see notes).':''}`,true);}));

let lastActivityReport=0;for(const name of ['keydown','pointerdown','pointermove','wheel'])document.addEventListener(name,event=>{if(!event.isTrusted||state.locked||Date.now()-lastActivityReport<10000)return;lastActivityReport=Date.now();call('app:activity').catch(()=>{});},{capture:true,passive:true});

$('check-updates').addEventListener('click',action(async()=>{const b=$('check-updates');b.disabled=true;b.textContent='Checking…';try{await call('update:check',{manual:true});}finally{b.disabled=false;b.textContent='Check for updates';}}));
